  "commands": [
    {
      "keystrokes": "cat > main.cpp << 'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nconst long long MOD = 1000000007LL;\n\nstruct Fenwick {\n    int n; vector<long long> bit;\n    Fenwick(int n_ = 0){ init(n_); }\n    void init(int n_){ n = n_; bit.assign(n+1, 0); }\n    void add(int idx, long long delta){\n        if(delta < 0) delta %= MOD, delta += MOD;\n        for(; idx <= n; idx += idx & -idx){\n            long long v = bit[idx] + delta;\n            v %= MOD;\n            bit[idx] = v;\n        }\n    }\n    long long sumPrefix(int idx){\n        long long res = 0;\n        for(; idx > 0; idx -= idx & -idx){\n            res += bit[idx];\n            if(res >= MOD) res -= MOD;\n        }\n        return res;\n    }\n    long long rangeSum(int l, int r){\n        if(r < l) return 0;\n        long long s = sumPrefix(r) - sumPrefix(l-1);\n        s %= MOD; if(s < 0) s += MOD;\n        return s;\n    }\n};\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n; if(!(cin>>n)) return 0;\n    vector<long long> p(n+1);\n    for(int i=1;i<=n;i++){ long long x; cin>>x; p[i] = x % MOD; }\n\n    // Precompute powers\n    vector<long long> pow2(n+2, 1), invpow2(n+3, 1);\n    long long inv2 = (MOD + 1) / 2; // 2^{-1} mod MOD\n    for(int i=1;i<=n+1;i++) pow2[i] = (pow2[i-1] * 2) % MOD;\n    for(int i=1;i<=n+2;i++) invpow2[i] = (invpow2[i-1] * inv2) % MOD;\n\n    Fenwick fw1(n), fw2(n);\n    long long totalVal2 = 0; // sum of p[i] * inv2^{i+1}\n    for(int i=1;i<=n;i++){\n        long long v1 = (p[i] * pow2[i]) % MOD;\n        long long v2 = (p[i] * invpow2[i+1]) % MOD;\n        fw1.add(i, v1);\n        fw2.add(i, v2);\n        totalVal2 += v2; if(totalVal2 >= MOD) totalVal2 -= MOD;\n    }\n\n    // Initial E: E = sum_{j=1..n} p[j] * ( sum_{i<j} p[i] * 2^{i} ) * 2^{-(j+1)}\n    long long E = 0;\n    long long T = 0; // sum_{i<j} p[i] * 2^{i}\n    for(int j=1;j<=n;j++){\n        long long S = (T * invpow2[j+1]) % MOD;\n        E = (E + p[j] * S) % MOD;\n        T = (T + p[j] * pow2[j]) % MOD;\n    }\n\n    cout << (E % MOD + MOD) % MOD << \"\\n\";\n\n    int q; cin >> q;\n    while(q--){\n        int idx; long long x; cin >> idx >> x;\n        x %= MOD;\n        long long old = p[idx];\n        long long delta = (x - old) % MOD; if(delta < 0) delta += MOD;\n\n        // Compute A_k = inv2^{k+1} * sum_{i<k} p[i] * 2^{i} + 2^{k} * sum_{i>k} p[i] * inv2^{i+1}\n        long long sumLeft = 0;\n        if(idx > 1) sumLeft = fw1.sumPrefix(idx-1);\n        long long term1 = (sumLeft * invpow2[idx+1]) % MOD;\n        long long sumRight = (totalVal2 - fw2.sumPrefix(idx)) % MOD; if(sumRight < 0) sumRight += MOD;\n        long long term2 = (sumRight * pow2[idx]) % MOD;\n        long long Ak = (term1 + term2) % MOD;\n\n        E = (E + delta * Ak) % MOD; if(E<0) E += MOD;\n\n        // Update data structures with new p[idx]\n        long long oldv2 = (old * invpow2[idx+1]) % MOD;\n        long long newv2 = (x * invpow2[idx+1]) % MOD;\n        totalVal2 = (totalVal2 - oldv2) % MOD; if(totalVal2 < 0) totalVal2 += MOD;\n        totalVal2 = (totalVal2 + newv2) % MOD;\n\n        fw1.add(idx, (delta * pow2[idx]) % MOD);\n        fw2.add(idx, (delta * invpow2[idx+1]) % MOD);\n        p[idx] = x;\n\n        cout << (E % MOD + MOD) % MOD << \"\\n\";\n    }\n\n    return 0;\n}\nCPP\n\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n./main << 'INPUT1'\n2\n1 2\n2\n1 2\n2 1\nINPUT1\n",
