#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if(!(cin >> N)) return 0;
    int K; int eps;
    cin >> K >> eps;
    double X0, Y0;
    cin >> X0 >> Y0;

    vector<double> D(N);
    double maxD = 0.0;
    for(int i = 0; i < N; ++i){
        double x, y; cin >> x >> y;
        double dx = x - X0, dy = y - Y0;
        double d = sqrt(dx*dx + dy*dy);
        D[i] = d;
        if(d > maxD) maxD = d;
    }

    auto p_of = [&](double dist, double R)->double {
        const double EPS = 1e-15;
        if (R < EPS) {
            return (dist <= 0.0 + EPS) ? 1.0 : 0.0;
        }
        if (dist <= R) return 1.0;
        return exp(- (dist - R) / R);
    };

    auto winProb = [&](double R)->double {
        vector<double> dp(N+1, 0.0), ndp(N+1, 0.0);
        dp[0] = 1.0;
        for(int i = 0; i < N; ++i){
            double p = p_of(D[i], R);
            fill(ndp.begin(), ndp.end(), 0.0);
            for(int j = 0; j <= i+1; ++j){
                double without = dp[j] * (1.0 - p);
                double with = (j > 0 ? dp[j-1] * p : 0.0);
                ndp[j] += without + with;
            }
            dp.swap(ndp);
        }
        double sum = 0.0;
        for(int j = K; j <= N; ++j) sum += dp[j];
        return sum;
    };

    double required = 1.0 - (double)eps / 1000.0;
    double lo = 0.0, hi = maxD;
    if (winProb(hi) < required) {
        hi = maxD * 2.0;
    }
    for(int it = 0; it < 100; ++it){
        double mid = (lo + hi) * 0.5;
        double w = winProb(mid);
        if (w >= required) hi = mid; else lo = mid;
    }

    cout.setf(std::ios::fixed); cout << setprecision(15) << hi << "\n";
    return 0;
}
